/** The adhkār for a time of day, with the right wording for it. */
export function adhkarFor(time: AdhkarTime): (Dhikr & { show: DhikrPart[]; meaning: string })[] {
  return ADHKAR.filter((d) => d.when === "both" || d.when === time).map((d) => ({
    ...d,
    show: time === "evening" && d.eveningParts ? d.eveningParts : d.parts,
    meaning: time === "evening" && d.enEvening ? d.enEvening : d.en,
  }));
}
